<template>
  <div class="main-data-container">

    <!-- ── 1. Лёгкий прелоадер (данные уже есть в кеше) ── -->
    <transition name="fade">
      <div class="light-preloader" v-if="isCacheLoad">
        <div class="lp-bar">
          <div class="lp-bar-fill"></div>
        </div>
        <div class="lp-text">Подготовка данных...</div>
      </div>
    </transition>

    <!-- ── 2. Полный степпер (первая загрузка) ─────────── -->
    <div class="loader-wrap" v-if="!isLoad && !isCacheLoad">
      <div class="spinner-only" v-if="!isPogress">
        <div class="orbit-spinner">
          <div class="orbit"></div>
          <div class="orbit"></div>
          <div class="orbit"></div>
        </div>
      </div>
      <div class="stepper-load" v-if="isPogress">
        <div class="top-bar">
          <div class="top-bar-fill" :style="{ width: progressWidth }"></div>
        </div>
        <div class="loader-title">Загрузка, пожалуйста подождите...</div>
        <div class="steps">
          <template v-for="(step, i) in loaderSteps" :key="step.key">
            <div v-if="i > 0" class="step-line">
              <div class="step-line-fill" :style="{ width: lineWidth(i) }"></div>
            </div>
            <div class="step">
              <div class="step-icon" :class="stepState(step.key)">
                <div v-if="stepState(step.key) === 'active'" class="step-spinner"></div>
                <span v-else-if="stepState(step.key) === 'done'">✓</span>
                <span v-else class="step-arrow">↓</span>
              </div>
              <div class="step-label" :class="stepState(step.key)">{{ step.label }}</div>
            </div>
          </template>
        </div>
      </div>
    </div>

    <!-- ── 3. Контент ─────────────────────────────────── -->
    <transition name="fade">
      <div class="main-data-body" v-if="isLoad">

        <!-- Кнопка выбора периода -->
        <div class="choosed-period">
          <div class="period-wrap">
            <button class="period-btn" :class="{ 'active-btn': periodOpen }" @click="periodOpen = !periodOpen">
              📅
              <div class="period-tooltip">{{ userTimeDate }}</div>
            </button>
            <div class="period-dropdown" v-if="periodOpen">
              <div class="dropdown-header">Выбор периода</div>
              <div
                  v-for="p in datePeriod" :key="p"
                  class="period-option" :class="{ active: p === userTimeDate }"
                  @click="userTimeDate = p; periodOpen = false"
              >
                {{ p }}
                <span v-if="p === userTimeDate" class="period-check">✓</span>
              </div>
            </div>
          </div>
        </div>

        <!-- Карточки по компании -->
        <div class="cards">
          <CardProductComponent :selected-date="userTimeDate"/>
          <CardServicesComponent :selected-date="userTimeDate"/>
          <CardTraficComponent :selected-date="userTimeDate"/>
          <CardConversionComponent :selected-date="userTimeDate"/>
          <CardCheckComponent :selected-date="userTimeDate"/>
          <CardCountComponent :selected-date="userTimeDate"/>
          <CardCreditComponent :selected-date="userTimeDate"/>
        </div>

        <div class="divider"></div>

        <!-- Графики -->
        <div class="charts">
          <AllManagersChart :selected-date="userTimeDate"/>
          <div class="divider"></div>
          <TraficManagerChart :selected-date="userTimeDate"/>
          <div class="divider"></div>
          <div class="secondary-manager-charts">
            <CheckManagersChart :selected-date="userTimeDate"/>
            <ConverciaManagersChart :selected-date="userTimeDate"/>
          </div>
          <div class="divider"></div>
          <div class="secondary-manager-charts">
            <CreditManagerChart :selected-date="userTimeDate"/>
            <CountManagersChart :selected-date="userTimeDate"/>
          </div>
        </div>

        <div class="divider"></div>

        <div class="summ-card">
          <SummaryCardComponent :selected-date="userTimeDate"/>
        </div>
      </div>
    </transition>

    <v-snackbar v-model="snackbar" color="error" timeout="4000">
      {{ snackbarText }}
    </v-snackbar>

  </div>
</template>

<script>
import $ from 'jquery'
import {dataStore} from '@/operations/requests'
import {MANAGERS} from '@/config/managers.config'

import CardProductComponent from '@/components/others/CardProductComponent.vue'
import CardServicesComponent from '@/components/others/CardServicesComponent.vue'
import CardTraficComponent from '@/components/others/CardTraficComponent.vue'
import CardConversionComponent from '@/components/others/CardConversionComponent.vue'
import CardCheckComponent from '@/components/others/CardCheckComponent.vue'
import CardCountComponent from '@/components/others/CardCountComponent.vue'
import CardCreditComponent from '@/components/others/CardCreditComponent.vue'
import SummaryCardComponent from '@/components/others/SummaryCardComponent.vue'

import AllManagersChart from '@/components/chart/AllManagersChart.vue'
import CheckManagersChart from '@/components/chart/CheckManagersChart.vue'
import ConverciaManagersChart from '@/components/chart/ConverciaManagersChart.vue'
import CreditManagerChart from '@/components/chart/CreditManagerChart.vue'
import TraficManagerChart from '@/components/chart/TraficManagerChart.vue'
import CountManagersChart from '@/components/chart/CountManagersChart.vue'

const COMPANY_URL = 'https://script.google.com/macros/s/AKfycbyrwwXDLpRnoee4iopb3qVYb8TuAEWfdBkQoCHbh4FzHSGvqAJozQCdPigbKZ5TO-77kA/exec'

export default {
  name: 'MainDataComponent',
  components: {
    CardProductComponent,
    CardServicesComponent,
    CardTraficComponent,
    CardConversionComponent,
    CardCheckComponent,
    CardCountComponent,
    CardCreditComponent,
    SummaryCardComponent,

    AllManagersChart,
    CheckManagersChart,
    ConverciaManagersChart,
    CreditManagerChart,
    TraficManagerChart,
    CountManagersChart,
  },
  data() {
    // Степпер и loadPersonalData генерируются из конфига
    const loaderSteps = [
      {key: 'company', label: 'Компания'},
      ...MANAGERS.map(m => ({key: m.id, label: m.name})),
    ]
    const loadPersonalData = Object.fromEntries(
        loaderSteps.map(s => [s.key, false])
    )

    return {
      screenWidth: window.innerWidth,
      isLoad: false,
      isPogress: false,
      isCacheLoad: false,
      snackbar: false,
      snackbarText: '',
      periodOpen: false,
      companyData: [],
      datePeriod: [],
      userTimeDate: '',
      loadPersonalData,
      loaderSteps,
    }
  },
  computed: {
    progressWidth() {
      const done = Object.values(this.loadPersonalData).filter(Boolean).length
      return Math.round((done / this.loaderSteps.length) * 100) + '%'
    },
  },
  methods: {
    stepState(key) {
      if (this.loadPersonalData[key]) return 'done'
      const keys = Object.keys(this.loadPersonalData)
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === key ? 'active' : 'pending'
    },

    lineWidth(i) {
      const keys = Object.keys(this.loadPersonalData)
      const prevKey = keys[i - 1]
      if (this.loadPersonalData[prevKey]) return '100%'
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === prevKey ? '40%' : '0%'
    },

    async getRequest() {
      const cached = dataStore.getCompanyData()

      if (cached) {
        this.companyData = [...cached]
        this.getAllPeriods()
        this.isCacheLoad = true
        setTimeout(() => {
          this.isCacheLoad = false
          this.isLoad = true
          localStorage.setItem('checkLoadStatus', 'loaded')
        }, 600)
        return
      }

      this.isPogress = true

      try {
        // Загрузка компании
        await $.ajax({
          url: COMPANY_URL, type: 'GET', crossDomain: true, dataType: 'json',
          success: (response) => {
            dataStore.setCompanyData(response.info)
            this.companyData = [...response.info]
            this.getAllPeriods()
            this.loadPersonalData.company = true
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных по компании'
            this.snackbar = true
            console.error(error)
          },
        })

        // Загрузка менеджеров — цикл по конфигу
        for (const manager of MANAGERS) {
          await $.ajax({
            url: manager.url, type: 'GET', crossDomain: true, dataType: 'json',
            success: (response) => {
              dataStore.setManagerData(manager.id, response[manager.dataKey])
              this.loadPersonalData[manager.id] = true
            },
            error: (error) => {
              this.snackbarText = `Ошибка загрузки данных ${manager.name}`
              this.snackbar = true
              console.error(error)
            },
          })
        }

      } catch (e) {
        console.error(e)
      }
    },

    getAllPeriods() {
      const periods = this.companyData.map(item => item.time).reverse()
      this.datePeriod = [...periods]
      this.userTimeDate = periods[0] || ''
    },

    updateWidth() {
      this.screenWidth = window.innerWidth
    },
  },
  watch: {
    loadPersonalData: {
      handler(val) {
        if (Object.values(val).every(Boolean)) {
          setTimeout(() => {
            this.isLoad = true
            localStorage.setItem('checkLoadStatus', 'loaded')
          }, 800)
        }
      },
      deep: true,
    },
  },
  created() {
    window.addEventListener('resize', this.updateWidth)
  },
  mounted() {
    this.getRequest()
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateWidth)
    localStorage.removeItem('checkLoadStatus')
  },
}
</script>

<style lang="scss" scoped>
.main-data-container {
  width: 100%;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  .summ-card {
    width: 100%;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }
}

.fade-enter-active {
  transition: opacity 0.4s ease;
}

.fade-leave-active {
  transition: opacity 0.25s ease;
}

.fade-enter-from, .fade-leave-to {
  opacity: 0;
}

// ── Лёгкий прелоадер ────────────────────────────────
.light-preloader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 60px 20px;
}

.lp-bar {
  width: 200px;
  height: 3px;
  background: #f0f2f7;
  border-radius: 2px;
  overflow: hidden;
}

.lp-bar-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, #f97316, #fbbf24);
  animation: lp-sweep 0.6s ease forwards;
}

@keyframes lp-sweep {
  from {
    width: 0;
  }
  to {
    width: 100%;
  }
}

.lp-text {
  font-size: 12px;
  font-weight: 600;
  color: #9ba3b8;
  letter-spacing: 0.4px;
}

// ── Орбитальный спиннер ─────────────────────────────
.spinner-only {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px;
}

.orbit-spinner {
  width: 56px;
  height: 56px;
  position: relative;

  .orbit {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 3px solid transparent;
    animation: orbit-spin 1.2s linear infinite;

    &:nth-child(1) {
      border-top-color: #f97316;
      animation-duration: 1.0s;
    }

    &:nth-child(2) {
      inset: 8px;
      border-right-color: #fbbf24;
      animation-duration: 1.4s;
      animation-direction: reverse;
    }

    &:nth-child(3) {
      inset: 16px;
      border-bottom-color: #f97316;
      animation-duration: 1.8s;
    }
  }
}

@keyframes orbit-spin {
  to {
    transform: rotate(360deg);
  }
}

// ── Степпер ─────────────────────────────────────────
.loader-wrap {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
}

.stepper-load {
  max-width: 780px;
  width: 100%;
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 20px;
  padding: 28px 32px 24px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, .04), 0 12px 28px rgba(0, 0, 0, .08);
  position: relative;
  overflow: hidden;
}

.top-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: #f0f2f7;
}

.top-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #f97316, #fb923c, #fbbf24);
  border-radius: 0 2px 2px 0;
  transition: width 0.5s ease;
  position: relative;

  &::after {
    content: '';
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #f97316;
    box-shadow: 0 0 8px rgba(249, 115, 22, .6);
  }
}

.loader-title {
  font-size: 13px;
  font-weight: 600;
  color: #6b7280;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 8px;

  &::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #f97316;
    box-shadow: 0 0 6px rgba(249, 115, 22, .5);
    animation: dot-pulse 1.2s ease-in-out infinite;
    flex-shrink: 0;
  }
}

@keyframes dot-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}

.steps {
  display: flex;
  align-items: center;
}

.step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.step-line {
  flex: 1;
  height: 2px;
  background: #e5e7eb;
  position: relative;
  margin-bottom: 28px;
  min-width: 20px;

  .step-line-fill {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    background: linear-gradient(90deg, #f97316, #fbbf24);
    border-radius: 1px;
    transition: width 0.5s ease;
  }
}

.step-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  transition: all 0.4s ease;
  background: #f3f4f6;
  border: 2px solid #e5e7eb;
  color: #9ca3af;

  &.done {
    background: linear-gradient(135deg, #f97316, #fbbf24);
    border-color: transparent;
    color: #fff;
    box-shadow: 0 4px 12px rgba(249, 115, 22, .35);
  }

  &.active {
    background: #fff;
    border-color: #f97316;
    color: #f97316;
    animation: ring-pulse 1.2s ease-in-out infinite;
  }
}

@keyframes ring-pulse {
  0%, 100% {
    box-shadow: 0 0 0 4px rgba(249, 115, 22, .12);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(249, 115, 22, .05);
  }
}

.step-spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(249, 115, 22, .2);
  border-top-color: #f97316;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.step-label {
  font-size: 11px;
  font-weight: 600;
  color: #9ca3af;
  transition: color 0.3s;
  white-space: nowrap;

  &.done {
    color: #1a1f36;
  }

  &.active {
    color: #f97316;
  }
}

// ── Контент ─────────────────────────────────────────
.main-data-body {
  width: 100%;
  position: relative;

  .choosed-period {
    display: flex;
    justify-content: flex-end;
    padding: 10px 20px 0;
    position: sticky;
    top: 70px;
    z-index: 10;
  }

  .period-wrap {
    position: relative;
  }

  .period-btn {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: #fff;
    border: 1px solid #e2e8f0;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .08);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 17px;
    transition: all 0.2s ease;
    position: relative;

    &:hover, &.active-btn {
      border-color: #6366f1;
      box-shadow: 0 2px 14px rgba(99, 102, 241, .2);
      transform: scale(1.05);
    }
  }

  .period-tooltip {
    position: absolute;
    top: 50%;
    right: calc(100% + 10px);
    transform: translateY(-50%);
    background: #1e293b;
    color: #fff;
    font-size: 12px;
    font-weight: 600;
    padding: 6px 12px;
    border-radius: 8px;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.15s ease;
    z-index: 200;

    &::after {
      content: '';
      position: absolute;
      top: 50%;
      left: 100%;
      transform: translateY(-50%);
      border: 5px solid transparent;
      border-left-color: #1e293b;
    }
  }

  .period-btn:hover .period-tooltip {
    opacity: 1;
  }

  .period-dropdown {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    background: #fff;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    box-shadow: 0 8px 28px rgba(0, 0, 0, .12);
    overflow: hidden;
    z-index: 100;
    min-width: 220px;
    animation: dd-in 0.15s ease;
  }

  @keyframes dd-in {
    from {
      opacity: 0;
      transform: translateY(-6px) scale(0.97);
    }
    to {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  .dropdown-header {
    padding: 10px 16px 8px;
    font-size: 10px;
    font-weight: 700;
    color: #94a3b8;
    letter-spacing: 1px;
    text-transform: uppercase;
    border-bottom: 1px solid #f1f5f9;
  }

  .period-option {
    padding: 10px 16px;
    font-size: 13px;
    font-weight: 500;
    color: #475569;
    cursor: pointer;
    transition: all 0.15s;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #f8fafc;

    &:last-child {
      border: none;
    }

    &:hover {
      background: #f8fafc;
      color: #1e293b;
    }

    &.active {
      background: linear-gradient(90deg, rgba(99, 102, 241, .06), transparent);
      color: #6366f1;
      font-weight: 700;
    }
  }

  .period-check {
    font-size: 12px;
    color: #6366f1;
  }

  .cards {
    display: flex;
    flex-direction: row;
    justify-content: center;
    gap: 30px;
    flex-wrap: wrap;
    margin: 10px auto 0;
  }

  .divider {
    width: 80%;
    margin: 50px auto;
    height: 3px;
    border-radius: 1px;
    background-image: linear-gradient(to right, transparent, rgba(255, 165, 0, .5), transparent);
  }

  .charts {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    .secondary-manager-charts {
      width: 100%;
      display: flex;
      flex-direction: row;
      justify-content: center;
      gap: 30px;
      flex-wrap: wrap;
    }
  }
}

// ── Адаптив ─────────────────────────────────────────
@media screen and (max-width: 768px) {
  .choosed-period {
    margin: 0 auto;
  }
}

@media screen and (max-width: 600px) {
  .stepper-load {
    padding: 20px 16px 16px;
    border-radius: 14px;
  }

  .loader-title {
    font-size: 11px;
    margin-bottom: 14px;
    justify-content: center;
    text-align: center;
  }

  /* Степпер — вертикально */
  .steps {
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    overflow-x: unset;
  }
  .step {
    flex-direction: row; /* иконка слева, подпись справа */
    align-items: center;
    gap: 12px;
    width: 100%;
  }
  .step-line {
    width: 2px;
    height: 20px;
    min-width: unset;
    margin-bottom: 0;
    margin-left: 15px; /* центрируем под иконкой 32px */
    flex: 0 0 2px;
  }
  .step-line-fill {
    width: 100% !important; /* перебиваем inline-style */
    height: 100%;
  }
  .step-icon {
    width: 32px;
    height: 32px;
    font-size: 12px;
    flex-shrink: 0;
  }
  .step-spinner {
    width: 14px;
    height: 14px;
  }
  .step-label {
    font-size: 12px;
    white-space: nowrap;
  }
}
</style>
