<template>
  <div class="chart-card">
    <div class="chart-header">
      <div class="chart-tag">Трафик</div>
      <h2 class="chart-title">Трафик по менеджерам</h2>
      <p class="chart-subtitle">{{ period }}</p>
    </div>
    <div class="grid">
      <div
          v-for="m in managers"
          :key="m.name"
          class="mc"
          :style="{ background: `linear-gradient(145deg, ${m.color}ee, ${m.color}99)` }"
      >
        <div class="mc-top">
          <div class="mc-name">{{ m.name }}</div>
          <div class="mc-pct-badge">{{ m.pct }}%</div>
        </div>

        <div class="gauge-wrap">
          <svg width="90" height="50" viewBox="0 0 90 50">
            <path d="M 10 45 A 35 35 0 0 1 80 45" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="7"
                  stroke-linecap="round"/>
            <path
                d="M 10 45 A 35 35 0 0 1 80 45"
                fill="none"
                stroke="rgba(255,255,255,0.85)"
                stroke-width="7"
                stroke-linecap="round"
                :stroke-dasharray="GAUGE_LEN"
                :stroke-dashoffset="gaugeOffset(m.pct)"
                class="gauge-progress"
            />
          </svg>
        </div>

        <div class="mc-fact">{{ fmt(m.trafic_f) }}</div>
        <div class="mc-fact-sub">посетителей</div>

        <div class="mc-divider"></div>

        <div class="mc-row">
          <span class="mc-row-label">План</span>
          <span class="mc-row-val">{{ fmt(m.trafic_p) }}</span>
        </div>
        <div class="mc-row">
          <span class="mc-row-label">Пр. год</span>
          <span class="mc-row-val">{{ fmt(m.trafic_past) }}</span>
        </div>

        <div class="mc-yoy">
          {{ m.yoy >= 0 ? '▲ +' : '▼ ' }}{{ m.yoy }}% к пр. году
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'
import { MANAGERS, getManagerColor } from '@/config/managers.config'

const GAUGE_LEN = 110
function fmt(v) {
  if (v == null) return '—'
  return Math.round(v).toLocaleString('ru-RU')
}

export default {
  name: 'TraficManagerChart',

  props: {
    selectedDate: {
      type: String,
      default: '',
    },
  },

  data() {
    return {
      managers: [],
      period: '',
      GAUGE_LEN,
    }
  },

  mounted() {
    this.setData()
  },

  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.setData()
      }
    },
  },

  methods: {
    setData() {
      const sources = MANAGERS.map(m => ({
        name: m.name,
        data: dataStore.getManagerData(m.id),
      }))

      const result = sources
          .filter(s => Array.isArray(s.data) && s.data.length)
          .map(s => {
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]

            if (!row) return null

            const pct = row.trafic_p
                ? Math.round((row.trafic_f / row.trafic_p) * 1000) / 10
                : 0
            const yoy = row.trafic_past
                ? Math.round(((row.trafic_f - row.trafic_past) / row.trafic_past) * 100)
                : 0

            return {
              name: s.name,
              color: getManagerColor(s.name),
              trafic_f: row.trafic_f ?? 0,
              trafic_p: row.trafic_p ?? 0,
              trafic_past: row.trafic_past ?? 0,
              pct,
              yoy,
            }
          })
          .filter(Boolean)

      if (!result.length) return

      this.managers = result.sort((a, b) => b.trafic_f - a.trafic_f)
      this.period = this.selectedDate || ''
    },

    gaugeOffset(pct) {
      return GAUGE_LEN - Math.min(pct / 150, 1) * GAUGE_LEN
    },

    fmt,
  },
}
</script>

