<template>
  <div class="chart-card">
    <div class="chart-header">
      <div>
        <div class="chart-tag">Кредитование</div>
        <h2 class="chart-title">Доля кредита в товарообороте</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
    </div>
    <div class="credit-legend">
      <div class="leg-item">
        <span class="leg-bar"></span>
        Факт %
      </div>
      <div class="leg-item">
        <span class="leg-line"></span>
        План %
      </div>
    </div>
    <div class="credit-grid">
      <div v-for="m in managers" :key="m.name" class="credit-row">

        <!-- Название -->
        <div class="cr-name">{{ m.name }}</div>

        <!-- Трек -->
        <div class="cr-col">
          <div class="cr-track-wrap">
            <!-- Подпись плана — над треком -->
            <div
                class="cr-plan-tip"
                :style="{ left: toW(m.credit_p) }"
            >
              {{ m.credit_p }}%
            </div>

            <div class="cr-track">
              <!-- Факт -->
              <div
                  class="cr-fact"
                  :style="{ width: toW(m.credit_f), background: m.color + 'cc' }"
              >
                <span class="cr-fact-label">{{ m.credit_f }}%</span>
              </div>

              <!-- Линия плана -->
              <div
                  class="cr-plan-line"
                  :style="{ left: toW(m.credit_p) }"
              ></div>
            </div>
          </div>

          <!-- Подпись % выполнения -->
          <div class="cr-footer">
            <span class="cr-footer-edge">0%</span>
            <span class="cr-footer-pct" :style="{ color: pctColor(m.pct) }">
              {{ m.pct >= 100 ? '▲' : '▼' }} {{ m.pct }}% от плана
            </span>
            <span class="cr-footer-edge">{{ maxCredit }}%</span>
          </div>
        </div>

        <!-- Сумма -->
        <div class="cr-sum">
          {{ fmtMln(m.credit_sum) }}
          <span class="cr-sum-sub">сумма кредита</span>
        </div>

      </div>
    </div>
  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'
import { MANAGERS, getManagerColor } from '@/config/managers.config'
function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90) return '#84cc16'
  if (p >= 80) return '#f59e0b'
  return '#ef4444'
}
function fmtMln(v) {
  if (v == null) return '—'
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2).replace('.', ',') + ' млн'
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
  return String(v)
}

export default {
  name: 'CreditManagerChart',
  props: {
    selectedDate: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      managers: [],
      period: '',
      maxCredit: 50,
    }
  },
  mounted() {
    this.setData()
  },
  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.setData()
      }
    },
  },
  methods: {
    setData() {
      const sources = MANAGERS.map(m => ({
        name: m.name,
        data: dataStore.getManagerData(m.id),
      }))

      const result = sources
          .filter(s => Array.isArray(s.data) && s.data.length)
          .map(s => {
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]

            if (!row) return null

            const pct = row.credit_p
                ? Math.round((row.credit_f / row.credit_p) * 1000) / 10
                : 0

            return {
              name: s.name,
              color: getManagerColor(s.name),
              credit_f: row.credit_f ?? 0,
              credit_p: row.credit_p ?? 0,
              credit_sum: row.credit_sum ?? 0,
              pct,
            }
          })
          .filter(Boolean)

      if (!result.length) return

      const allVals = result.flatMap(m => [m.credit_f, m.credit_p])
      this.maxCredit = Math.ceil(Math.max(...allVals) * 1.3)
      this.managers = result.sort((a, b) => b.credit_f - a.credit_f)
      this.period = this.selectedDate || ''
    },

    toW(val) {
      if (!this.maxCredit) return '0%'
      return Math.min((val / this.maxCredit) * 100, 100) + '%'
    },

    pctColor,
    fmtMln,
  },
}
</script>

